import { describe, expect, test } from "bun:test";
import {
  applyRow,
  consistent,
  formatColor,
  makeTransform,
  parseContourPoints,
  transformContour,
  type ImageFile,
} from "../src/dicom";

// Test vectors generated by running the Python roimath.py math with
// numpy (points.dot(make_transform(iop, ipp))).
const iop = [
  -8.3346015e-2, 9.9652019e-1, -9.7995078e-4, 1.2180652e-4, -9.7318472e-4,
  -9.9999952e-1,
];
const ipp = [-3.59993e-1, -223.741, 261.634];
const points = [
  [-14.611, -53.268, 88.894, 1],
  [-14.622, -53.135, -14.8, 1],
  [-14.8, -51.007, -51.007, 1],
  [-14.811, -50.874, 88.892, 1],
];

describe("makeTransform", () => {
  test("matches numpy", () => {
    const want = [
      [1.7123682769079431e2, 1.7257227950045825e2],
      [1.7147189669841063e2, 2.7626609895389879e2],
      [1.7364280833129209e2, 3.1247098895589409e2],
      [1.7363916818855586e2, 1.7257192533397458e2],
    ];
    const xform = makeTransform(iop, ipp);
    points.forEach((p, i) => {
      const got = applyRow(p, xform);
      expect(Math.abs(got[0]! - want[i]![0]!)).toBeLessThan(1e-9);
      expect(Math.abs(got[1]! - want[i]![1]!)).toBeLessThan(1e-9);
    });
  });

  test("transformContour truncates like numpy astype(int)", () => {
    const got = transformContour(points, makeTransform(iop, ipp), [0.5, 0.5]);
    expect(got).toEqual([
      [342, 345],
      [342, 552],
      [347, 624],
      [347, 345],
    ]);
  });
});

describe("consistent", () => {
  const mk = (fileId: number, z: number): ImageFile => ({
    fileId,
    path: "",
    imageType: [],
    frameCount: 1,
    orientation: [1, 0, 0, 0, 1, 0],
    position: [0, 0, z],
  });

  test("sorts by projected position", () => {
    const [sorted, volumetric] = consistent([mk(1, 5), mk(2, -3), mk(3, 1)]);
    expect(volumetric).toBeTrue();
    expect(sorted.map((f) => f.fileId)).toEqual([2, 3, 1]);
  });

  test("edge cases are non-volumetric", () => {
    expect(consistent([])[1]).toBeFalse();
    expect(consistent([mk(1, 0)])[1]).toBeFalse();
    const missingGeom = [mk(1, 0), { ...mk(2, 0), orientation: [], position: [] }];
    expect(consistent(missingGeom)[1]).toBeFalse();
  });
});

describe("parseContourPoints", () => {
  test("parses homogeneous 4-vectors", () => {
    expect(parseContourPoints("1\\2\\3\\4\\5\\6")).toEqual([
      [1, 2, 3, 1],
      [4, 5, 6, 1],
    ]);
  });
  test("rejects non-3d contours", () => {
    expect(() => parseContourPoints("1\\2")).toThrow();
  });
});

describe("formatColor", () => {
  test("parses r\\g\\b", () => {
    expect(formatColor("255\\0\\128")).toEqual([255, 0, 128]);
  });
  test("defaults to black", () => {
    expect(formatColor("")).toEqual([0, 0, 0]);
    expect(formatColor(null)).toEqual([0, 0, 0]);
    expect(formatColor("1\\2")).toEqual([0, 0, 0]);
    expect(formatColor("a\\b\\c")).toEqual([0, 0, 0]);
  });
});
